/**
 * @fileoverview A package that calls a callback from the bottom of a recursion of its own.
 * @module callback-walker
 */

/**
 * Call `callback` from `depth` frames of this function.
 * @param {number} depth - How deep to recurse.
 * @param {function(): *} callback - What to call.
 * @returns {*} What the callback returned.
 * @example
 * descend(3, () => 1); // 1
 */
export function descend(depth, callback) {
	return depth > 0 ? descend(depth - 1, callback) : callback();
}
